//       mov eax, [eax]       ; srm->end()
//       mov ecx, [eax+8]     ; begin
//       cmp ecx, eax
//       mov [esp+0x14], ecx  ; srmIt
//   and at +0x1bc it re-derives the bound from that slot:
//       mov ecx, [esp+0x24]  ; srm
//       mov edx, [ecx]       ; *srm == srm->end()
//   This shape dereferences first and caches the end NODE in the slot the map
//   pointer would have used, so the head store lands after the deref and the
//   tail's `mov edx,[ecx]` disappears.
//   The head half already matches in the re-derived form: the deref form emits
//   `mov [slot],eax; mov eax,[eax]` in the same order retail does.  The ONLY
//   remaining difference is that MSVC 7.1 gives the loop-carried node a
//   callee-saved REGISTER (ebp, pushed shrink-wrapped at +0x97) instead of a
//   stack slot, which drops the frame from 0x3c to 0x38 and reallocates every
//   displacement.  The zero register then moves from ebp to ebx and
//   `getGameSpySlot(0)` becomes `push 0` instead of `push ebp`.
//   Counting explains the strict bimodality: the cached-end form has TWO
//   loop-carried values (node + end) and MSVC spills both; the re-derived form
